// This function checks if a given text contains any references to marijuana
function containsMarijuanaReference(text) {
    // List of keywords related to marijuana
    const marijuanaKeywords = ['marijuana', 'cannabis', 'weed', 'pot', 'ganja', 'hash', 'THC'];

    // Convert the text to lowercase for case-insensitive comparison
    const lowerCaseText = text.toLowerCase();

    // Check if any of the keywords are present in the text
    for (let keyword of marijuanaKeywords) {
        if (lowerCaseText.includes(keyword)) {
            return true; // Return true if a keyword is found
        }
    }

    return false; // Return false if no keywords are found
}

