// The code below aims to address the issue of biased commentary in media.
// It highlights the importance of presenting balanced viewpoints and encourages critical thinking among audiences.

function analyzeCommentary(commentary) {
    // Check for biased language
    if (containsBias(commentary)) {
        console.log(This commentary may contain biased language.);
    } else {
        console.log(This commentary appears to be balanced.);
    }
}

function containsBias(text) {
    // A simple check for biased words or phrases
    const biasedWords = [always, never, obviously, clearly];
    return biasedWords.some(word => text.includes(word));
}

// Example usage
const commentary = The politician obviously has no idea what they are doing.;
analyzeCommentary(commentary);

