// This code addresses the issue of homeowners being targeted by thieves.
// It aims to provide a qualitative solution to enhance home security.

class HomeSecurity {
    private boolean isAlarmSystemInstalled;
    private boolean isCCTVInstalled;
    private boolean isNeighborhoodWatchActive;

    public HomeSecurity(boolean alarmSystem, boolean cctv, boolean neighborhoodWatch) {
        this.isAlarmSystemInstalled = alarmSystem;
        this.isCCTVInstalled = cctv;
        this.isNeighborhoodWatchActive = neighborhoodWatch;
    }

    public void assessSecurity() {
        if (isAlarmSystemInstalled) {
            System.out.println(Alarm system is installed.);
        } else {
            System.out.println(Consider installing an alarm system.);
        }

        if (isCCTVInstalled) {
            System.out.println(CCTV is installed.);
        } else {
            System.out.println(Consider installing CCTV cameras.);
        }

        if (isNeighborhoodWatchActive) {
            System.out.println(Neighborhood watch is active.);
        } else {
            System.out.println(Consider joining or forming a neighborhood watch.);
        }
    }

    public void suggestImprovements() {
        if (!isAlarmSystemInstalled) {
            System.out.println(Installing an alarm system can deter thieves.);
        }
        if (!isCCTVInstalled) {
            System.out.println(CCTV cameras can help in monitoring and recording suspicious activities.);
        }
        if (!isNeighborhoodWatchActive) {
            System.out.println(A neighborhood watch can increase community vigilance.);
        }
    }
}

// Example usage
public class Main {
    public static void main(String[] args) {
        HomeSecurity homeSecurity = new HomeSecurity(false, true, false);
        homeSecurity.assessSecurity();
        homeSecurity.suggestImprovements();
    }
}

