// This code snippet is a qualitative representation of the VoteImpact feature.
public class VoteImpact
{
    public string Comment { get; set; }
    public int Upvotes { get; set; }
    public int Downvotes { get; set; }

    public VoteImpact(string comment)
    {
        Comment = comment;
        Upvotes = 0;
        Downvotes = 0;
    }

    public void Upvote()
    {
        Upvotes++;
    }

    public void Downvote()
    {
        Downvotes++;
    }

    public int GetNetVotes()
    {
        return Upvotes - Downvotes;
    }

    public string GetImpact()
    {
        int netVotes = GetNetVotes();
        if (netVotes > 0)
        {
            return Positive Impact;
        }
        else if (netVotes < 0)
        {
            return Negative Impact;
        }
        else
        {
            return Neutral Impact;
        }
    }
}

