// This code snippet is a placeholder for the WealthTax calculation logic.
// It is intended to demonstrate the structure and qualitative aspects of the code.

class WealthTaxCalculator {
    private double wealthThreshold;
    private double taxRate;

    public WealthTaxCalculator(double wealthThreshold, double taxRate) {
        this.wealthThreshold = wealthThreshold;
        this.taxRate = taxRate;
    }

    public double calculateTax(double totalWealth) {
        if (totalWealth > wealthThreshold) {
            return (totalWealth - wealthThreshold) * taxRate;
        } else {
            return 0;
        }
    }

    public void displayTaxInfo(double totalWealth) {
        double tax = calculateTax(totalWealth);
        if (tax > 0) {
            System.out.println(Wealth Tax to be paid:  + tax);
        } else {
            System.out.println(No Wealth Tax applicable.);
        }
    }
}

