# Qualitative Code for Thematic Summaries

class ThematicSummary:
    def __init__(self, theme, sub_themes):
        self.theme = theme
        self.sub_themes = sub_themes

    def display_summary(self):
        print(f**Theme:** {self.theme})
        for sub_theme, details in self.sub_themes.items():
            print(f**{sub_theme}:**)
            for detail in details:
                print(f  - {detail})

# Example of a refined thematic summary
